import {renderLearning,learningClick,learningChange,getLearningTopic} from './learning.js';
import {modules,corpus} from './learning-engine.js';
import {catalog,escapeHtml as e} from './core.js';
import {createBrowserOllama} from './browser-ollama.js';
const panel=document.querySelector('#panel'),params=new URLSearchParams(location.search);
const read=k=>{try{return localStorage.getItem(k)||'';}catch{return '';}};
const save=(k,v)=>{try{localStorage.setItem(k,v);}catch{message('This browser cannot save preferences. Keep a backup of your work.',true);}};
let tab=['tutor','quiz','history','setup'].includes(params.get('tool'))?params.get('tool'):'home',busy=false,connected=false,version='',installed=[],excluded=0,chosen=read('soma-ai-model'),download=catalog.some(m=>m.tag===read('soma-ai-download'))?read('soma-ai-download'):catalog[0].tag,error=null,progress=null,checked=false,checkSeconds=null,os='windows',guide=0;
const bridge=createBrowserOllama({onProgress:p=>{progress=p;render();}}),invoke=(cmd,args)=>bridge.invoke(cmd,args);
const current=()=>modules.find(m=>m.id===getLearningTopic())||modules[0];
const chapterOf=m=>Number(m.section.split('.')[0]);
function message(text,isError=false){const el=document.querySelector('#message');el.textContent=text;el.classList.toggle('error',isError);}
function button(id,label,primary=false,disabled=false){return `<button id="${id}" ${busy||disabled?'disabled':''} class="${primary?'primary':''}">${label}</button>`;}
function chapterLink(){return current().studioUrl||'../chapter3/#module/'+current().id+'/learn';}
function home(){const m=current(),chapter=chapterOf(m);panel.innerHTML=`<div class="grid"><article class="card"><p class="eyebrow">CHAPTER ${chapter} · ${e(m.section)}</p><h2>Your lesson. Your questions. Your pace.</h2><p>${e(m.title)}</p><div class="study-actions"><button data-tab="tutor"><b>Ask your tutor →</b><span>Build understanding one question at a time.</span></button><button data-tab="quiz"><b>Generate practice →</b><span>New questions, explanations and useful feedback.</span></button><a class="button" href="${e(chapterLink())}"><b>Return to the lesson →</b><span>Diagrams and reviewed practice remain available without AI.</span></a></div><div class="connection"><b>${connected?'● Connected to Ollama':'○ Connect when you’re ready'}</b>${!connected?button('connect','Connect to Ollama',true):'<button data-tab="setup">Model & connection settings</button>'}</div><small>Only Ollama is required. Soma runs here in your browser.</small></article><aside class="card"><p class="eyebrow">YOUR TEXTBOOK</p><h2>Keep the chapter in view.</h2><div class="book-grid">${modules.filter(x=>chapterOf(x)===chapter).map(x=>`<a class="book-link" href="${e(corpus.find(r=>r.module===x.id)?.url||'https://openstax.org/books/anatomy-and-physiology-2e/pages/'+chapter+'-introduction')}" target="_blank" rel="noopener"><span>${x.section}</span>${e(x.title)} ↗</a>`).join('')}</div><p class="muted">${e(m.coverage||'Authored studio lessons support this chapter.')} AI explanations can need correction.</p></aside></div>`;}
function guideContent(){const origin=location.origin,steps=[
 {title:'Install and open Ollama',body:`<p>Ollama is the only program you need. If you already have it, open it from your Start menu or Applications folder.</p><div class="row"><a class="button primary" href="ollama://">Open Ollama</a><a class="button" href="https://ollama.com/download" target="_blank" rel="noopener">Get Ollama ↗</a></div><p class="muted">The Open button works when Ollama has registered its app link. Your browser may ask to open the app. If nothing happens, open Ollama yourself and return here.</p>`},
 {title:'Allow this website once',body:`<p>Ollama needs permission to accept requests from this website. This setting stays on your computer.</p><label for="setup-os">Your operating system</label><select id="setup-os">${[['windows','Windows'],['mac','macOS'],['linux','Linux']].map(([v,t])=>`<option value="${v}" ${os===v?'selected':''}>${t}</option>`).join('')}</select>${os==='windows'?`<ol class="setup-instructions"><li>Quit Ollama from its icon near the Windows clock.</li><li>Open Start and search <b>Edit environment variables for your account</b>.</li><li>Under <b>User variables</b>, choose <b>New</b>, or edit the existing variable below.</li><li>Save with OK, then reopen Ollama from Start.</li></ol><div class="config-example"><span>Variable name</span><code>OLLAMA_ORIGINS</code><span>Variable value</span><code>${e(origin)}</code></div>`:os==='mac'?`<p>Quit Ollama, open Terminal, and set its allowed website:</p><code class="config-command">launchctl setenv OLLAMA_ORIGINS "${e(origin)}"</code><p>Then reopen the Ollama application.</p>`:`<p>For the standard systemd installation, run <code>sudo systemctl edit ollama.service</code>. Add:</p><code class="config-command">[Service]<br>Environment="OLLAMA_ORIGINS=${e(origin)}"</code><p>Save, then run <code>sudo systemctl daemon-reload</code> and <code>sudo systemctl restart ollama</code>.</p>`}<p class="muted">If OLLAMA_ORIGINS already exists, add this origin to its comma-separated list. Keep the existing entries. This authorizes this website’s origin, including its other pages, not just one chapter. Keep Ollama’s default local-only network address.</p><a href="https://docs.ollama.com/faq#how-can-i-allow-additional-web-origins-to-access-ollama" target="_blank" rel="noopener">Official Ollama instructions ↗</a>`},
 {title:'Connect and choose your model',body:`<p>Click <b>Connect to Ollama</b>. If your browser asks whether this site may connect to your local network, allow it to reach Ollama on this computer.</p><p>If you previously blocked the request, open this website’s permissions using the icon beside its address. In Chrome or Edge, look for local network or loopback access, allow it, reload this page, and connect again.</p><div class="row">${button('connect','Connect to Ollama',true)}<a href="https://support.microsoft.com/en-gb/topic/control-a-website-s-access-to-the-local-network-in-microsoft-edge-ef7eff4c-676d-4105-935c-2acbcd841d51" target="_blank" rel="noopener">Edge permission guide ↗</a></div><p class="muted">A failed connection does not tell us whether Ollama is missing, stopped or blocked. Work through these steps in order. A school-managed browser may restrict local connections.</p>`}
 ];return `<div class="guide-step"><p class="eyebrow">SETUP STEP ${guide+1} OF 3</p><h3>${steps[guide].title}</h3>${steps[guide].body}<div class="row guide-pager">${button('guide-prev','← Previous',false,guide===0)}<span>${guide+1} / 3</span>${button('guide-next','Next step →',false,guide===2)}</div></div>`;}
function setup(){const selected=catalog.find(m=>m.tag===download);panel.innerHTML=`<div class="setup-layout"><article class="card wizard"><p class="eyebrow">BROWSER AI · ONLY OLLAMA REQUIRED</p><h2>${connected?'Choose your study partner.':'Let’s connect your tutor.'}</h2><div class="connection"><b>${connected?'● Connected · Ollama '+e(version):'○ Not connected'}</b>${button('connect',connected?'Refresh connection':'Connect to Ollama',true)}</div>${connected?`<label for="model">Downloaded local models</label><select id="model" ${busy?'disabled':''}><option value="">Choose a model</option>${installed.map(m=>`<option value="${e(m.name)}" ${chosen===m.name?'selected':''}>${e(m.name)} · ${(m.size/1e9).toFixed(1)} GB</option>`).join('')}</select>${!installed.length?'<p>No local chat models were found. Download one below to begin.</p>':''}${excluded?`<p class="muted">${excluded} cloud or non-chat model(s) excluded.</p>`:''}<div class="row">${button('verify','Check this model',false,!chosen)}<button data-tab="tutor" class="primary" ${busy||!chosen?'disabled':''}>Ask your tutor →</button><button data-tab="quiz" ${busy||!chosen?'disabled':''}>Generate practice →</button></div>${checked?`<p class="model-success">✓ This model responded on this computer in ${checkSeconds}s. This checks operation, not answer accuracy.</p>`:''}<details ${!installed.length?'open':''}><summary>Download another model</summary><label for="download-model">Choose a model</label><select id="download-model" ${busy?'disabled':''}>${catalog.map(m=>`<option value="${m.tag}" ${download===m.tag?'selected':''}>${m.label} · about ${m.gb} GB</option>`).join('')}</select><p class="muted">${download===catalog[0].tag?'The compact model is a conservative starting point. ':''}About ${selected.gb} GB to download, plus working space. Larger models can be slower or exceed available memory. Browser mode cannot measure your free VRAM.</p>${button('download','Download selected model',true)}<p class="muted">Models are saved in Ollama’s configured folder. Keep this tab open for progress. <a href="https://ollama.com/library/qwen3.5/tags" target="_blank" rel="noopener">Model details and license ↗</a></p></details>`:guideContent()}<details><summary>Model storage & privacy</summary><p>Ollama manages the model folder. To use a different drive, follow its <a href="https://docs.ollama.com/faq#where-are-models-stored" target="_blank" rel="noopener">model-storage instructions</a> before downloading. Soma cannot inspect or move these files from a browser.</p><p>Soma checks model metadata and rejects cloud-backed models. You can also enable Ollama’s documented <code>OLLAMA_NO_CLOUD=1</code> setting. This browser connects to <code>127.0.0.1:11434</code>; it does not use a hosted AI proxy.</p><p>Saved conversations stay in this browser’s storage. Export them in Saved work. Website and model downloads still use the internet.</p></details>${connected?`<details><summary>Connection troubleshooting</summary>${guideContent()}</details>`:''}</article><aside class="card setup-help"><p class="eyebrow">READ → REASON → RECALL</p><h2>One setup for every chapter.</h2><p>Your model choice works across all available chapters. Enter from a lesson and its topic follows you.</p><a class="button" href="${e(chapterLink())}">Keep studying →</a><p class="muted">No Soma installer, extension or subscription. Open Ollama on the same computer as this browser.</p><p class="muted">A phone’s localhost is the phone itself. This connection does not access Ollama on another device.</p></aside></div>`;}
function render(){const open=[...panel.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent),focused=document.activeElement?.id;document.body.dataset.tool=tab;document.querySelectorAll('.tabs [data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false');});if(tab==='home')home();else if(tab==='setup')setup();else renderLearning({panel,tab,busy,ready:connected,chosen,installed,invoke,work,message,render,setTab:t=>{tab=t;render();}});if(error||progress||busy){const box=document.createElement('div');box.className='task-banner';box.innerHTML=error?`<b>${e(error.title)}</b><p>${e(error.message)}</p>${error.code==='connection'||error.code==='origin'?'<button data-tab="setup">Connection help</button>':''}`:`<b>${e(progress?.status||'Working with Ollama…')}</b>${progress?.total?`<progress max="${Number(progress.total)}" value="${Number(progress.completed)||0}"></progress><small>${Math.min(100,Math.floor(100*(progress.completed||0)/progress.total))}% of this download layer</small>`:'<progress aria-label="Working"></progress>'}<button id="cancel">Stop waiting</button>`;panel.prepend(box);}for(const d of panel.querySelectorAll('details'))if(open.includes(d.querySelector('summary')?.textContent))d.open=true;if(focused)document.getElementById(focused)?.focus({preventScroll:true});}
async function work(fn){if(busy)return;busy=true;error=null;render();try{await fn();}catch(err){if(['connection','origin'].includes(err.code)){connected=false;checked=false;}error={code:err.code||'response',title:err.code==='cancelled'?'Request interrupted':err.code==='connection'?'Not connected yet':'This step needs attention',message:String(err.message||err)};message(error.message,true);}finally{busy=false;progress=null;render();}}
async function connect(){tab='setup';progress={status:'Connecting to Ollama on this computer…'};render();connected=false;const status=await invoke('status');const models=await invoke('models');version=status.version;installed=models.models;excluded=models.excluded;connected=true;if(!installed.some(m=>m.name===chosen))chosen=installed[0]?.name||'';save('soma-ai-model',chosen);checked=false;message(installed.length?'Connected. Choose a model, then return to your tutor or quiz.':'Connected. Download a local chat model to begin.');}
async function verify(){if(!chosen)throw Error('Choose a local model first.');progress={status:'Loading your model and checking a short response…'};render();const start=performance.now();const response=await invoke('chat',{model:chosen,messages:[{role:'user',content:'Reply with the single word Ready.'}],format:null});if(!response.message?.content?.trim())throw Error('The model did not return a response. Try another local model.');checkSeconds=((performance.now()-start)/1000).toFixed(1);checked=true;message('Your model responded. You can start studying.');}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;if(b.id==='cancel'){await invoke('cancel_job');return;}if(b.dataset.tab){if(busy){message('Finish or stop the current request before switching tools.');return;}tab=b.dataset.tab;error=null;render();return;}if(busy)return;if(b.id==='connect'){await work(connect);return;}if(b.id==='verify'){await work(verify);return;}if(b.id==='guide-prev'||b.id==='guide-next'){guide+=b.id==='guide-next'?1:-1;render();return;}if(b.id==='download'){await work(async()=>{save('soma-ai-download',download);progress={status:'Preparing your model download…'};render();await invoke('pull_model',{model:download});const data=await invoke('models');installed=data.models;excluded=data.excluded;chosen=installed.find(m=>m.name===download)?.name||'';save('soma-ai-model',chosen);checked=false;message('Download complete. Select your model and check it when ready.');});return;}if(!['home','setup'].includes(tab))await learningClick(b);});
document.addEventListener('change',async ev=>{const t=ev.target;if(['model','learning-model'].includes(t.id)){chosen=t.value;checked=false;save('soma-ai-model',chosen);render();}else if(t.id==='download-model'){download=t.value;render();}else if(t.id==='setup-os'){os=t.value;render();}else await learningChange(ev);});
document.addEventListener('input',ev=>{if(['tutor-input','quiz-answer'].includes(ev.target.id))learningChange(ev);});
window.addEventListener('beforeunload',ev=>{if(busy){ev.preventDefault();ev.returnValue='';}});
document.body.dataset.browser='true';document.querySelector('#web-note').hidden=true;render();
